python3 << 'EOF'
import json
import subprocess

test_cases = [
    ("Example from requirement", {
        "pipeline": {"steps": [
            {"op": "select", "columns": ["id", "customer_lifetime_value_including_all_historic_orders_and_refunds"]}
        ]},
        "dataset": []
    }),
    ("Select with valid 64-char column", {
        "pipeline": {"steps": [
            {"op": "select", "columns": ["id", "a" * 64]}
        ]},
        "dataset": []
    }),
    ("Filter with too-long where", {
        "pipeline": {"steps": [
            {"op": "filter", "where": "x" * 65}
        ]},
        "dataset": []
    }),
    ("Map with valid 64-char as", {
        "pipeline": {"steps": [
            {"op": "map", "as": "b" * 64, "expr": "1"}
        ]},
        "dataset": []
    }),
    ("Rename mapping with control char", {
        "pipeline": {"steps": [
            {"op": "rename", "mapping": {"old": "new\nline"}}
        ]},
        "dataset": []
    }),
    ("Branch with valid 64-char id", {
        "pipeline": {"steps": [
            {"op": "branch", "branches": [
                {"id": "c" * 64, "when": "x > 0", "steps": []}
            ]}
        ]},
        "dataset": []
    }),
    ("Merge strategy with control char", {
        "pipeline": {"steps": [
            {"op": "branch", "branches": [
                {"when": "x > 0", "steps": []}
            ], "merge": {"strategy": "concat\t"}}
        ]},
        "dataset": []
    }),
    ("Valid complex pipeline", {
        "pipeline": {"steps": [
            {"op": "select", "columns": ["id"]},
            {"op": "filter", "where": "id > 0"},
            {"op": "map", "as": "squared", "expr": "id * id"},
            {"op": "rename", "mapping": {"id": "identifier"}},
            {"op": "limit", "n": 100}
        ]},
        "dataset": [{"id": 1}, {"id": 2}]
    })
]

for name, test_input in test_cases:
    result = subprocess.run(
        ["python", "etl_pipeline.py"],
        input=json.dumps(test_input),
        capture_output=True,
        text=True
    )

    output = json.loads(result.stdout)
    status = output.get('status')
    error_code = output.get('error_code', 'N/A')
    path = output.get('path', 'N/A')

    print(f"{name}:")
    print(f"  Status: {status}, Error code: {error_code}, Path: {path}")
    if status == 'error':
        print(f"  Message: {output['message']}")
    print()
EOF
